import { supabase } from '../lib/supabase';
import { werseeAi } from '../ai/client';

export type StorefrontProvider = 'gumroad' | 'whop' | 'website';

export type StorefrontPreviewProduct = {
  sourceKey: string;
  sourceId: string;
  sourceUrl: string;
  title: string;
  headline: string;
  description: string;
  price: string;
  currency: string;
  imageUrls: string[];
  category: string | null;
};

export type StorefrontAnalysis = {
  importId: string;
  sourceUrl: string;
  provider: StorefrontProvider;
  storeName: string;
  products: StorefrontPreviewProduct[];
  warnings: string[];
  supportsCodebaseUpload: boolean;
  importEngine?: 'web_scrape' | 'supabase_whop';
};

export type StorefrontCommitResult = {
  importId: string;
  status: 'completed' | 'partial' | 'failed';
  importedCount: number;
  imported: Array<{
    sourceKey: string;
    listingId: string;
    title: string;
    status: 'imported' | 'already_imported';
    imageUrl?: string | null;
    mediaWarnings: string[];
  }>;
  failed: Array<{ sourceKey: string; title: string; error: string }>;
};

export type StorefrontProductPlacement = {
  sourceKey: string;
  kind: 'product' | 'digital' | 'service' | 'course' | 'community';
  category: string;
  heroImageIndex: number;
  layout: 'product' | 'editorial' | 'gallery' | 'service';
};

export class StorefrontImportApiError extends Error {
  constructor(public code: string, message: string, public status = 400) {
    super(message);
  }
}

const invokeWhop = async <T>(body: Record<string, unknown>): Promise<T> => {
  const { data, error } = await supabase.functions.invoke('whop-connection', { body });
  if (error || data?.error) {
    let payload = data;
    if (!payload && error && 'context' in error && error.context instanceof Response) {
      payload = await error.context.clone().json().catch(() => null);
    }
    throw new StorefrontImportApiError(
      payload?.error?.code || 'WHOP_CONNECTION_FAILED',
      payload?.error?.message || error?.message || 'Wersee could not complete the Whop account connection.',
      error && 'context' in error && error.context instanceof Response ? error.context.status : 400,
    );
  }
  return data as T;
};

const isWhopStorefront = (value: string) => {
  try {
    const url = new URL(value.includes('://') ? value : `https://${value}`);
    const hostname = url.hostname.toLowerCase();
    return hostname === 'whop.com' || hostname.endsWith('.whop.com');
  } catch {
    return false;
  }
};

const request = async <T>(path: string, body: Record<string, unknown>): Promise<T> => {
  const { data } = await supabase.auth.getSession();
  const token = data.session?.access_token;
  if (!token) throw new StorefrontImportApiError('AUTH_REQUIRED', 'Sign in to import a storefront.', 401);
  const response = await fetch(`/api/storefront-import/${path}`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  });
  const payload = await response.json().catch(() => null);
  if (!response.ok) {
    throw new StorefrontImportApiError(
      payload?.error?.code || 'STOREFRONT_IMPORT_FAILED',
      payload?.error?.message || 'Wersee could not complete the storefront import.',
      response.status,
    );
  }
  return payload as T;
};

export const analyzeStorefrontUrl = async (url: string) => {
  if (isWhopStorefront(url) || /^biz_[A-Za-z0-9_-]+$/.test(url.trim())) {
    const result = await invokeWhop<{ catalog: StorefrontAnalysis }>({
      action: 'connect',
      storefrontUrl: url,
    });
    return result.catalog;
  }
  return request<StorefrontAnalysis>('analyze', { url });
};

export const commitStorefrontImport = (
  importId: string,
  products: Array<{ sourceKey: string; title: string; headline: string; organization?: Omit<StorefrontProductPlacement, 'sourceKey'> }>,
  importEngine: StorefrontAnalysis['importEngine'] = 'web_scrape',
) => importEngine === 'supabase_whop'
  ? invokeWhop<StorefrontCommitResult>({ action: 'import', importId, products })
  : request<StorefrontCommitResult>('commit', { importId, products });

export const organizeStorefrontProducts = async (products: StorefrontPreviewProduct[]) => {
  const response = await werseeAi.organizeStorefront({
    products: products.map((product) => ({
      sourceKey: product.sourceKey,
      title: product.title,
      headline: product.headline,
      description: product.description,
      category: product.category,
      imageCount: Math.min(product.imageUrls.length, 8),
    })),
  });
  if (!response.sourceCopyPreserved) throw new Error('Wersee AI could not guarantee source-copy preservation.');
  return response;
};
